{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Digitoxin absolute oral bioavailability was >90% in humans versus IV, showing that a steroid-like molecule can be essentially completely absorbed; this high-transfer evidence supports F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "β-Methyldigoxin systemic availability was 76±2% versus IV in humans, another steroid-like molecule with high oral bioavailability, supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Ursodeoxycholic acid systemic availability was 50% in healthy subjects versus IV, demonstrating that a steroid with hepatic first-pass can still exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C65"],
      "claim": "Ethinylestradiol absolute bioavailability was 47.3±7.5% in healthy women, a steroid with first-pass metabolism but F well above 20%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Lefamulin absolute oral bioavailability was 25.8% in fasted healthy adults, showing that even drugs with substantial first-pass metabolism can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Perindopril absolute oral bioavailability was about 75%, supporting high oral F for a drug-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Amphotericin B has negligible oral bioavailability, but this reflects a large polyene macrolide with poor permeability and solubility, a mechanism not shared by the small steroid-like query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a steroid-like corticosteroid acetal (desisobutyryl-ciclesonide active metabolite). High-transfer evidence from steroid and drug-like molecules shows absolute oral bioavailability values mostly ≥20% (digitoxin >90%, β-methyldigoxin 76%, UDCA 50%, ethinylestradiol ~47%, lefamulin ~26%, perindopril ~75%). The only strong low-F evidence (amphotericin B) reflects a large polyene with poor permeability not shared by the query. Therefore F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for a corticosteroid 16α,17α-acetal (e.g., ciclesonide active metabolite or budesonide) is present in the evidence set.",
    "The query's exact F is uncertain near the 20% threshold; corticosteroid first-pass metabolism could reduce F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

